python3 -c "
import json
with open('/app/resources/treasury_bulletin_1946_07.json', 'r') as f:
    data = json.load(f)

# Look for any keys containing payroll
def find_keys(obj, prefix=''):
    if isinstance(obj, dict):
        for k, v in obj.items():
            if 'payroll' in k.lower():
                print(f'Found: {prefix}{k}')
            find_keys(v, prefix + k + '.')
    elif isinstance(obj, list) and len(obj) > 0:
        find_keys(obj[0], prefix + '[0].')

find_keys(data)
